gnal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period:\n        return None, None, None\n    prices_arr = np.array(prices, dtype=float)\n    short_ema_full = calculate_ema_series(prices_arr, short_period)\n    long_ema_full = calculate_ema_series(prices_arr, long_period)\n    macd_line = short_ema_full[len(short_ema_full)-len(long_ema_full):] - long_ema_full\n    if len(macd_line) < signal_period:\n        return macd_line, None, None\n    signal_line = calculate_ema_series(macd_line, signal_period)\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    return macd_line, signal_line, histogram\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    price_ranges = np.abs(np.diff(prices_arr))\n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_roc(prices, period=20):\n    """Calculates the Rate of Change (ROC) over a given period."""\n    if len(prices) < period + 1:\n        return None\n    return ((prices[-1] - prices[-1 - period]) / prices[-1 - period]) * 100\n\ndef calculate_bollinger_bands(prices, period=20, num_std_dev=2):\n    """Calculates Bollinger Bands and Band Width."""\n    if len(prices) < period:\n        return None, None, None, None, None\n    prices_arr = np.array(prices, dtype=float)\n    \n    # Calculate band width series for squeeze detection\n    rolling_mean = np.array([np.mean(prices_arr[i-period:i]) for i in range(period, len(prices_arr) + 1)])\n    rolling_std = np.array([np.std(prices_arr[i-period:i]) for i in range(period, len(prices_arr) + 1)])\n    \n    upper_bands = rolling_mean + (rolling_std * num_std_dev)\n    lower_bands = rolling_mean - (rolling_std * num_std_dev)\n    \n    # Avoid division by zero\n    safe_rolling_mean = np.where(rolling_mean == 0, 1e-9, rolling_mean)\n    band_widths = (upper_bands - lower_bands) / safe_rolling_mean\n    \n    return upper_bands[-1], rolling_mean[-1], lower_bands[-1], band_widths[-1], band_widths\n\ndef decide(current_price, price_history, news_context):\n    """\n    SELF-IMPROVED STRATEGY V3:\n    This version integrates Bollinger Bands to create a more adaptive, volatility-aware\n    system. Key improvements include:\n    1.  Dynamic Entry/Exit Signals: Instead of fixed RSI levels, it uses Bollinger\n        Bands to identify dynamic overbought/oversold conditions. This includes two\n        new buy triggers: buying dips to the lower band in an uptrend and buying\n        volatility breakouts from a "Bollinger Squeeze."\n    2.  Enhanced Confirmation: Sell signals for profit-taking now require confirmation\n        from both RSI and a price breach above the upper Bollinger Band, reducing\n        premature exits in strong trends.\n    3.  Refined Sentiment Context: The sentiment keyword dictionary is expanded with\n        more nuanced economic terms like "GDP growth" and "consumer confidence" to\n        better capture the macroeconomic environment.\n    """\n    # --- 1. Sentiment Analysis ---\n    context_lower = news_context.lower()\n    sentiment_keywords = {\n        # Positive\n        "fed pivot": 3.0, "rate cut": 2.5, "quantitative easing": 2.5, "soft landing": 2.5,\n        "cooling inflation": 2.5, "cpi miss": 2.5, "ai boom": 2.5, "stimulus": 2.0,\n        "dovish": 2.0, "record high": 2.0, "bullish": 2.0, "strong earnings": 2.0,\n        "beat estimates": 1.5, "recovery": 1.5, "upgrade": 1.5, "gdp growth": 2.0,\n        "consumer confidence": 2.0, "de-escalation": 2.0, "short squeeze": 3.5,\n        "capitulation": 3.0, "panic selling": 2.5, "extreme fear": 2.0,\n        # Ambiguous\n        "strong jobs report": 0.5,\n        # Negative\n        "recession": -3.0, "crisis": -3.0, "stagflation": -3.0, "hot inflation": -3.0,\n        "war": -3.0, "yield curve inversion": -3.5, "quantitative tightening": -2.5,\n        "black swan": -4.0, "systemic risk": -4.0, "contagion": -3.5, "credit crunch": -3.5,\n        "rate hike": -2.5, "bankruptcy": -2.5, "hard landing": -2.5, "geopolitical risk": -2.5,\n        "cpi beat": -2.5, "vix spike": -2.5, "hawkish": -2.0, "bearish": -2.0,\n        "sell-off": -2.0, "weak earnings": -2.0, "market turmoil": -2.0, "bubble": -2.0,\n        "uncertainty": -1.5, "liquidity crisis": -3.5,\n        "euphoria": -2.5, "mania": -3.0, "irrational exuberance": -3.0, "extreme greed": -2.5,\n    }\n    negation_words = ["not", "no", "lack of", "fail to", "without", "struggle to", "avoids", "prevent"]\n    net_sentiment_score = 0.0\n    for keyword, weight in sentiment_keywords.items():\n        pattern = r'\\b' + re.escape(keyword) + r'\\b'\n        for match in re.finditer(pattern, context_lower):\n            pre_context = context_lower[max(0, match.start() - 30):match.start()]\n            is_negated = any(neg_word in pre_context for neg_word in negation_words)\n            net_sentiment_score += -weight if is_negated else weight\n\n    # --- 2. Technical Indicators & State Calculation ---\n    all_prices = price_history + [current_price]\n\n    # Indicator Periods\n    SMA_TREND_LONG = 100\n    SMA_TREND_MEDIUM = 50\n    RSI_PERIOD = 14\n    BB_PERIOD = 20\n    BB_SQUEEZE_LOOKBACK = 60 # Lookback for detecting lowest band width\n    ROC_CRASH_PERIOD = 20\n    STOP_LOSS_LOOKBACK = 20\n\n    required_history_length = max(SMA_TREND_LONG + 1, BB_PERIOD + BB_SQUEEZE_LOOKBACK, 65)\n    if len(all_prices) < required_history_length:\n        return "HOLD"\n\n    # Calculate core indicators\n    sma_100 = calculate_sma(all_prices, SMA_TREND_LONG)\n    sma_50 = calculate_sma(all_prices, SMA_TREND_MEDIUM)\n    rsi = calculate_rsi(all_prices, RSI_PERIOD)\n    _, _, macd_hist_series = calculate_macd_series(all_prices)\n    roc_20 = calculate_roc(all_prices, ROC_CRASH_PERIOD)\n    donchian_high_20 = np.max(all_prices[-STOP_LOSS_LOOKBACK:])\n    \n    # Calculate Bollinger Bands and Squeeze indicator\n    bb_upper, bb_middle, bb_lower, bb_width, bb_width_series = calculate_bollinger_bands(all_prices, BB_PERIOD)\n    is_bb_squeeze = bb_width < np.min(bb_width_series[-BB_SQUEEZE_LOOKBACK:-1]) if bb_width_series is not None and len(bb_width_series) >= BB_SQUEEZE_LOOKBACK else False\n\n    # Null check for all indicators\n    if any(v is None for v in [sma_100, sma_50, rsi, roc_20, bb_upper]) or macd_hist_series is None or len(macd_hist_series) < 2:\n        return "HOLD"\n\n    macd_histogram = macd_hist_series[-1]\n    prev_macd_histogram = macd_hist_series[-2]\n    macd_hist_delta = macd_histogram - prev_macd_histogram\n\n    # --- 3. Regime Detection ---\n    is_long_term_downtrend = current_price < sma_100\n    is_crash_velocity = roc_20 < -15.0\n    is_crisis_regime = is_long_term_downtrend or is_crash_velocity\n\n    is_deeply_oversold = rsi < 25\n    is_extreme_crash_velocity = roc_20 < -18.0\n    is_capitulation_candidate = is_extreme_crash_velocity and is_deeply_oversold\n\n    # --- 4. Decision Logic (Hierarchical) ---\n\n    # REGIME 1: CONTRARIAN CAPITULATION (HIGHEST PRIORITY)\n    if is_capitulation_candidate and macd_hist_delta > 0:\n        return "BUY"\n\n    # REGIME 2: CRISIS AVERSION\n    if is_crisis_regime:\n        if macd_histogram < 0 or current_price < sma_50:\n            return "SELL"\n        return "HOLD"\n\n    # REGIME 3: NORMAL MARKET CONDITIONS\n\n    # --- SELL LOGIC (Risk Management First) ---\n    # Priority 1: Dynamic Stop-Loss (7% drop from 20-day high).\n    if current_price < (donchian_high_20 * 0.93):\n        return "SELL"\n\n    # Priority 2: Trend Breakdown Signal.\n    is_trend_breakdown = current_price < sma_50 and all_prices[-2] >= sma_50\n    is_momentum_confirming_down = macd_histogram < 0\n    if is_trend_breakdown and is_momentum_confirming_down:\n        return "SELL"\n\n    # Priority 3: Profit-taking on overbought conditions with fading momentum.\n    is_overextended = current_price > bb_upper and rsi > 78\n    is_momentum_fading = macd_hist_delta < 0\n    if is_overextended and is_momentum_fading:\n        return "SELL"\n\n    # --- BUY LOGIC ---\n    is_primary_uptrend = current_price > sma_50\n    is_not_overbought = rsi < 75\n    is_sentiment_permissive = net_sentiment_score > -3.0\n\n    if is_primary_uptrend and is_not_overbought and is_sentiment_permissive:\n        # Signal 1: Buy the dip to the lower Bollinger Band in an uptrend.\n        buy_the_dip_signal = current_price <= bb_lower\n\n        # Signal 2: Volatility breakout from a Bollinger Squeeze.\n        breakout_signal = is_bb_squeeze and current_price > bb_upper\n\n        # Signal 3: Classic momentum confirmation (MACD histogram crossover).\n        momentum_crossover_signal = macd_histogram > 0 and prev_macd_histogram <= 0\n\n        if buy_the_dip_signal or breakout_signal or momentum_crossover_signal:\n            return "BUY"\n\n    # Default action is to hold the current position.\n    return "HOLD"	0a6da0752f0862c82938597fdb6039f2dcf1aaaf971102a774ee9c47b53f8d52	This self-improved strategy enhances the parent by introducing Bollinger Bands for dynamic, volatility-based signals. This refines "Normal Market" logic by adding two new buy triggers: buying dips to the lower band during an uptrend and buying volatility breakouts from a "Bollinger Squeeze." Sell signals are also improved, requiring both high RSI and a price breach of the upper band for more robust profit-taking. The successful crisis and capitulation regimes are preserved, while sentiment analysis is updated with more nuanced economic keywords for better context awareness.	4730f2f6-58c1-4c71-9af0-1c05dbc5d276	2026-06-01 23:14:00.068762-04
a6f16617-9a54-4708-a903-a7f088b32ce2	54	evolution_gen_54	import numpy as np\nimport re\nimport math\n\n# --- Helper Functions for Technical Indicators ---\n\ndef calculate_ema_series(data, period):\n    """Calculates a full series of Exponential Moving Averages."""\n    if len(data) < period:\n        return np.array([])\n    data_arr = np.array(data, dtype=float)\n    try:\n        import pandas as pd\n        return pd.Series(data_arr).ewm(span=period, adjust=False).mean().to_numpy()[period-1:]\n    except ImportError:\n        ema_values = np.zeros(len(data_arr) - period + 1, dtype=float)\n        ema_values[0] = np.mean(data_arr[:period])\n        multiplier = 2 / (period + 1)\n        for i in range(1, len(ema_values)):\n            ema_values[i] = (data_arr[i + period - 1] - ema_values[i-1]) * multiplier + ema_values[i-1]\n        return ema_values\n\ndef calculate_sma(prices, period):\n    """Calculates the Simple Moving Average (SMA) for the latest price."""\n    if len(prices) < period:\n        return None\n    return np.mean(prices[-period:])\n\ndef calculate_rsi(prices, period=14):\n    """Calculates the Relative Strength Index (RSI) using Wilder's smoothing method."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    seed_gains = deltas[:period][deltas[:period] >= 0].sum()\n    seed_losses = -deltas[:period][deltas[:period] < 0].sum()\n    avg_gain = seed_gains / period\n    avg_loss = seed_losses / period\n    for i in range(period, len(deltas)):\n        delta = deltas[i]\n        gain = delta if delta >= 0 else 0.0\n        loss = -delta if delta < 0 else 0.0\n        avg_gain = (avg_gain * (period - 1) + gain) / period\n        avg_loss = (avg_loss * (period - 1) + loss) / period\n    if avg_loss == 0:\n        return 100.0\n    rs = avg_gain / avg_loss\n    return 100.0 - (100.0 / (1.0 + rs))\n\ndef calculate_macd_series(prices, short_period=12, long_period=26, signal_period=9):\n    """Calculates the MACD line, signal line, and histogram series."""\n    if len(prices) < long_period:\n        return None, None, None\n    short_ema_series = calculate_ema_series(prices, short_period)\n    long_ema_series = calculate_ema_series(prices, long_period)\n    macd_line = short_ema_series[len(short_ema_series)-len(long_ema_series):] - long_ema_series\n    if len(macd_line) < signal_period:\n        return macd_line, None, None\n    signal_line = calculate_ema_series(macd_line, signal_period)\n    histogram = macd_line[len(macd_line)-len(signal_line):] - signal_line\n    return macd_line, signal_line, histogram\n\ndef calculate_atr(prices, period=14):\n    """Calculates Average True Range (ATR) using close-to-close volatility."""\n    if len(prices) < period + 1:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    price_ranges = np.abs(np.diff(prices_arr))\n    atr_series = calculate_ema_series(price_ranges, period)\n    return atr_series[-1] if len(atr_series) > 0 else None\n\ndef calculate_adx(prices, period=14):\n    """\n    Calculates the Average Directional Index (ADX) using only closing prices.\n    This is a proxy as traditional ADX uses High, Low, and Close.\n    """\n    if len(prices) < 2 * period:\n        return None\n    prices_arr = np.array(prices, dtype=float)\n    deltas = np.diff(prices_arr)\n    \n    up_moves = np.where(deltas > 0, deltas, 0)\n    down_moves = np.where(deltas < 0, -deltas, 0)\n    \n    tr = np.abs(deltas)\n    \n    atr = calculate_ema_series(tr, period)\n    smoothed_up = calculate_ema_series(up_moves, period)\n    smoothed_down = calculate_ema_series(down_moves, period)\n\n    if atr is None or len(atr) == 0 or smoothed_up is None or smoothed_down is None:\n        return None\n        \n    plus_di = 100 * (smoothed_up / atr)\n    minus_di = 100 * (smoothed_down / atr)\n    \n    # Ensure lengths match for DX calculation\n    min_len = min(len(plus_di), len(minus_di))\n    plus_di = plus_di[-min_len:]\n    minus_di = minus_di[-min_len:]\n\n    sum_di = plus_di + minus_di\n    # Avoid division by zero\n    sum_di[sum_di == 0] = 1e-10\n    \n    dx = 100 * (np.abs(plus_di - minus_di) / sum_di)\n    \n    if len(dx) < period:\n        return None\n        \n    adx = calculate_ema_series(dx, period)\n    return adx[-1] if len(adx) > 0 else None\n\ndef decide(current_price, price_history, news_context):\n    """\n    SELF-IMPROVED STRATEGY V3:\n    This version enhances the V2 strategy with four key upgrades for robustness:\n    1.  Dynamic ATR Stop-Loss: Replaces the fixed percentage stop-loss with a\n        dynamic, ATR-based trailing stop to adapt risk management to market volatility.\n    2.  ADX Trend Strength Filter: Adds an ADX filter to BUY signals to ensure\n        entries occur during strong directional trends, reducing whipsaw losses.\n    3.  Enhanced Volatility Regime Detection: Uses the standard deviation of recent\n        returns to more accurately detect volatility spikes and shifts into crisis regimes.\n    4.  Sentiment Density Scoring: Normalizes the sentiment score by news context\n        length, measuring sentiment "density" to avoid dilution by long, neutral articles.\n    """\n    # --- 1. Sentiment Analysis ---\n    context_lower = news_context.lower()\n    sentiment_keywords = {\n        "fed pivot": 3.0, "rate cut": 2.5, "quantitative easing": 2.5, "soft landing": 2.5,\n        "cooling inflation": 2.5, "ai boom": 2.5, "stimulus": 2.0, "dovish": 2.0,\n        "record high": 2.0, "bullish": 2.0, "strong earnings": 2.0, "short squeeze": 3.5,\n        "capitulation": 3.0, "panic selling": 2.5, "extreme fear": 2.0,\n        "recession": -3.0, "crisis": -3.0, "stagflation": -3.0, "hot inflation": -3.0,\n        "war": -3.0, "yield curve inversion": -3.5, "quantitative tightening": -2.5,\n        "black swan": -4.0, "systemic risk": -4.0, "contagion": -3.5, "credit crunch": -3.5,\n        "rate hike": -2.5, "bankruptcy": -2.5, "hard landing": -2.5, "vix spike": -2.5,\n        "hawkish": -2.0, "bearish": -2.0, "sell-off": -2.0, "bubble": -2.0,\n        "uncertainty": -1.5, "euphoria": -2.5, "mania": -3.0, "extreme greed": -2.5,\n    }\n    negation_words = ["not", "no", "lack of", "fail to", "without", "struggle to", "avoids", "prevent"]\n    raw_sentiment_score = 0.0\n    keyword_count = 0\n    for keyword, weight in sentiment_keywords.items():\n        pattern = r'\\b' + re.escape(keyword) + r'\\b'\n        matches = list(re.finditer(pattern, context_lower))\n        if matches:\n            keyword_count += len(matches)\n            for match in matches:\n                pre_context = context_lower[max(0, match.start() - 30):match.start()]\n                is_negated = any(neg_word in pre_context for neg_word in negation_words)\n                raw_sentiment_score += -weight if is_negated else weight\n    \n    # Normalize score to create a "density" metric\n    word_count = len(context_lower.split())\n    net_sentiment_score = (raw_sentiment_score / (word_count + 1)) * 100 if word_count > 0 else 0.0\n\n    # --- 2. Technical Indicators & State Calculation ---\n    all_prices = price_history + [current_price]\n\n    # Indicator Periods\n    SMA_TREND_LONG = 100\n    SMA_TREND_MEDIUM = 50\n    RSI_PERIOD = 14\n    ATR_PERIOD = 14\n    ADX_PERIOD = 14\n    ROC_CRASH_PERIOD = 20\n    STOP_LOSS_LOOKBACK = 20\n    VOLATILITY_PERIOD = 20\n\n    required_history_length = max(SMA_TREND_LONG + 1, 2 * ADX_PERIOD, VOLATILITY_PERIOD + 2)\n    if len(all_prices) < required_history_length:\n        return "HOLD"\n\n    # Calculate core indicators\n    sma_100 = calculate_sma(all_prices, SMA_TREND_LONG)\n    sma_50 = calculate_sma(all_prices, SMA_TREND_MEDIUM)\n    rsi = calculate_rsi(all_prices, RSI_PERIOD)\n    _, _, macd_hist_series = calculate_macd_series(all_prices)\n    atr = calculate_atr(all_prices, ATR_PERIOD)\n    adx = calculate_adx(all_prices, ADX_PERIOD)\n    roc_20 = 